cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int feature_idx = blockIdx.y;

    if (batch_idx >= batch_size || feature_idx >= features) return;

    // Shared memory for reduction
    extern __shared__ float shared_data[];

    const int tid = threadIdx.x;
    const int total_elements = dim1 * dim2;

    float sum = 0.0f;

    // Compute sum of squares for this feature
    for (int i = tid; i < total_elements; i += blockDim.x) {
        const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        const float val = __half2float(input[idx]);
        sum += val * val;
    }

    shared_data[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    // Only thread 0 computes RMS and writes output
    if (tid == 0) {
        const float rms = sqrtf(shared_data[0] / total_elements + eps);

        // Write normalized output
        for (int i = 0; i < total_elements; i++) {
            const int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
            output[idx] = __float2half(__half2float(input[idx]) / rms);
        }
    }
}

// Optimized version using warp-level primitives
__global__ void rms_norm_kernel_optimized(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int features,
    const int dim1,
    const int dim2
) {
    const int batch_idx = blockIdx.x;
    const int feature_idx = blockIdx.y;

    if (batch_idx >= batch_size || feature_idx >= features) return;

    const int total_elements = dim1 * dim2;
    const int elements_per_thread = (total_elements + blockDim.x - 1) / blockDim.x;

    float sum = 0.0f;

    // Each thread processes multiple elements
    for (int i = 0; i < elements_per_thread; i++) {
        const int idx = i * blockDim.x + threadIdx.x;
        if (idx < total_elements) {
            const int global_idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + idx;
            const float val = __half2float(input[global_idx]);
            sum += val * val;
        }
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    // Only first thread of each warp computes RMS and writes output
    if (threadIdx.x % 32 == 0) {
        const float rms = sqrtf(sum / total_elements + eps);

        // Write normalized output
        for (int i = 0; i < total_elements; i++) {
            const int global_idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
            output[global_idx] = __float2half(__half2float(input[global_idx]) / rms);
        }
    }
}
"""

